#include <stdio.h>
/* 坏宏：多条语句直接拼，没有用 do-while(0) 包裹 */
#define LOG_BAD(x)  printf("A:%d\n", x); printf("B:%d\n", x)
/* 好宏：用 do-while(0) 包裹成单一语句 */
#define LOG_OK(x)  do { printf("A:%d\n", x); printf("B:%d\n", x); } while (0)

int main(void) {
    int n = 3, k;
    printf("=== LOG_BAD：期望循环 3 次各打印 A、B，但实际 B 只打印一次 ===\n");
    for (k = 0; k < n; k++)
        LOG_BAD(k);          /* 展开：printf(A); printf(B);  —— for 只管第一句 */
    printf("=== LOG_OK：do-while(0) 让宏成为单语句，循环行为正确 ===\n");
    for (k = 0; k < n; k++)
        LOG_OK(k);
    return 0;
}
